+"use client";
+
+import { ChevronDown } from "lucide-react";
+import { useEffect, useMemo, useRef, useState } from "react";
+
+const MAGIC_WORD = "capybara";
+const CAPYBARA_GIF =
+  "https://media.tenor.com/SyCURpdnbdUAAAAC/capybara-dancing-capybara.gif";
+const STAR_COUNT = 150;
+
+interface Star {
+  left: number;
+  top: number;
+  size: number;
+  peak: number;
+  duration: string;
+  delay: string;
+}
+
+function randomBetween(min: number, max: number) {
+  return Math.random() * (max - min) + min;
+}
+
+function generateStars(count: number): Star[] {
+  return Array.from({ length: count }, () => ({
+    left: randomBetween(0, 100),
+    top: randomBetween(0, 100),
+    size: randomBetween(1, 3),
+    peak: randomBetween(0.3, 1),
+    duration: `${randomBetween(2, 6).toFixed(2)}s`,
+    delay: `${randomBetween(0, 5).toFixed(2)}s`,
+  }));
+}
+
+export default function SussySandwichShoutout() {
+  const stars = useMemo(() => generateStars(STAR_COUNT), []);
+  const [revealed, setRevealed] = useState(false);
+  const bufferRef = useRef("");
+
+  useEffect(() => {
+    const onKeyDown = (event: KeyboardEvent) => {
+      if (event.metaKey || event.ctrlKey || event.altKey) return;
+      const key = event.key.toLowerCase();
+      if (!/^[a-z]$/.test(key)) {
+        bufferRef.current = "";
+        return;
+      }
+      bufferRef.current = (bufferRef.current + key).slice(-MAGIC_WORD.length);
+      if (bufferRef.current === MAGIC_WORD) {
+        setRevealed(true);
+      }
+    };
+
+    window.addEventListener("keydown", onKeyDown);
+    return () => window.removeEventListener("keydown", onKeyDown);
+  }, []);
+
+  return (
+    <main className="relative min-h-screen overflow-x-hidden text-white">
+      <style>{`
+        @keyframes twinkle {
+          0%, 100% { opacity: 0.1; }
+          50% { opacity: var(--star-peak, 1); }
+        }
+        @keyframes pop-in {
+          0% { opacity: 0; transform: scale(0.5); }
+          70% { opacity: 1; transform: scale(1.05); }
+          100% { opacity: 1; transform: scale(1); }
+        }
+        @keyframes name-flash {
+          0%, 100% { transform: scale(1) rotate(0deg); }
+          25% { transform: scale(1.15) rotate(2deg); }
+          50% { transform: scale(1.02) rotate(-2deg); }
+          75% { transform: scale(1.1) rotate(2deg); }
+        }
+        @keyframes float-down {
+          0%, 100% { transform: translateY(0); opacity: 0.7; }
+          50% { transform: translateY(8px); opacity: 1; }
+        }
+      `}</style>
+
+      <div
+        className="absolute inset-0"
+        style={{
+          background:
+            "linear-gradient(180deg, #03030d 0%, #070718 30%, #0f0824 60%, #1a0a35 88%, #240d45 100%)",
+        }}
+      />
+
+      <div className="absolute inset-0 pointer-events-none">
+        {stars.map((star, index) => (
+          <span
+            key={index}
+            className="absolute rounded-full bg-white"
+            style={
+              {
+                left: `${star.left}%`,
+                top: `${star.top}%`,
+                width: star.size,
+                height: star.size,
+                "--star-peak": star.peak,
+                animation: `twinkle ${star.duration} ease-in-out ${star.delay} infinite`,
+              } as React.CSSProperties
+            }
+          />
+        ))}
+      </div>
+
+      <section className="relative flex min-h-screen flex-col items-center justify-center px-4 py-20 text-center">
+        <div className="max-w-3xl" style={{ animation: "pop-in 0.8s ease 0.5s both" }}>
+          <h1 className="text-2xl font-bold text-indigo-200 sm:text-4xl">
+            Shoutout to
+          </h1>
+          <div
+            className="mt-2"
+            style={{ animation: "name-flash 2s ease-in-out 1s infinite" }}
+          >
+            <h2 className="text-4xl font-extrabold sm:text-6xl md:text-7xl bg-clip-text text-transparent bg-linear-to-r from-cyan-300 via-fuchsia-400 to-indigo-400">
+              SussySandwich445
+            </h2>
+          </div>
+          <p className="mt-6 text-xl font-medium text-purple-200 sm:text-2xl">
+            Very Cool Person!
+          </p>
+          <p className="mt-2 text-lg text-indigo-300/80 sm:text-xl">
+            You&apos;re out of this world. Keep coding through the cosmos.
+          </p>
+        </div>
+
+        <div className="absolute bottom-4 flex animate-[float-down_1.5s_ease-in-out_infinite] flex-col items-center">
+          <ChevronDown className="h-8 w-8 text-indigo-300/70" />
+        </div>
+      </section>
+
+      <section className="relative flex min-h-[60vh] flex-col items-center justify-start px-4 pt-24 pb-24 text-center">
+        <p className="text-sm tracking-widest text-violet-300/40">
+          psst... there&apos;s a secret down here.
+        </p>
+        <p className="mt-2 text-xs text-violet-300/30">
+          try typing the magic word
+        </p>
+
+        <div className="mt-16 flex flex-col items-center">
+          {revealed ? (
+            <div style={{ animation: "pop-in 0.6s ease both" }}>
+              <p className="mb-4 text-lg font-semibold text-fuchsia-300">
+                You found the secret capybara!
+              </p>
+              <img
+                src={CAPYBARA_GIF}
+                alt="A dancing capybara"
+                width={280}
+                height={498}
+                className="mx-auto max-w-xs rounded-2xl border border-white/10 shadow-2xl shadow-purple-950/60"
+              />
+            </div>
+          ) : (
+            <div className="flex h-[360px] w-[280px] items-center justify-center rounded-2xl border border-dashed border-white/10 bg-white/5">
+              <span className="text-4xl text-violet-300/30">???</span>
+            </div>
+          )}
+        </div>
+      </section>
+    </main>
+  );
+}
