"use client";

import { useCallback, useEffect, useMemo, useReducer, useState } from "react";

const MAGIC_WORD = "capybara";
const CAPYBARA_GIF = "https://media.tenor.com/SyCURpdnbdUAAAAC/capybara-dancing-capybara.gif";

const STAR_COUNT = 150;

interface Star {
  left: string;
  top: string;
  size: number;
  duration: string;
  delay: string;
  baseOpacity: number;
}

function randomBetween(min: number, max: number) {
  return Math.random() * (max - min) + min;
}

function generateStars(count: number): Star[] {
  return Array.from({ length: count }, (_, i) => ({
    left: `${randomBetween(0, 100)}%`,
    top: `${randomBetween(0, 100)}%`,
    size: randomBetween(1, 3),
    duration: `${randomBetween(2, 6)}s`,
    delay: `${randomBetween(0, 5)}s`,
    baseOpacity: randomBetween(0.3, 1),
  }));
}

export default function SussySandwichShoutout() {
  const stars = useMemo(() => generateStars(STAR_COUNT), []);
  const [revealed, setRevealed] = useState(false);
  const bufferRef = useRef("");

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const key = e.key.toLowerCase();
      if (!/^[a-z]$/.test(key)) {
        bufferRef.current = "";
        return;
      }
      bufferRef.current = (bufferRef.current + key).slice(-MAGIC_WORD.length);
      if (bufferRef.current === MAGIC_WORD) {
        setRevealed(true);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  return (
    <main className="relative min-h-screen overflow-hidden">
      <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, #04040f 0%, #0a0a26 40%, #120a2e 75%, #1b0c38 100%)" }} />
      {/* stars */}
      <div className="absolute inset-0">
        {stars.map((star, i) => (
          <span
            key={i}
            className="absolute rounded-full bg-white"
            style={{
              left: star.left,
              top: star.top,
              width: star.size,
              height: star.size,
              opacity: star.baseOpacity,
              animation: `twinkle ${star.duration} ease-in-out ${star.delay} infinite`,
            }}
          />
        ))}
      </div>
      {/* a couple of planets */}
      <div ... /> 
      content...
    </main>
  );
}
