let last = performance.now();
const tick = (now) => {
  const dt = Math.min(0.05, (now-last)/1000);
  last = now;
  t += dt;
  ctx.clearRect(0,0,width,height);

  for p of particles:
    // hover bubble repel
    const dx = p.x - mouse.x; const dy = p.y - mouse.y;
    const dist = Math.hypot(dx, dy);
    if (dist < BUBBLE_RADIUS && dist > 0.001) {
      const force = ((BUBBLE_RADIUS - dist)/BUBBLE_RADIUS) * 0.35;
      p.vx += (dx/dist) * force * dt * 60; // scaled
      p.vy += (dy/dist) * force * dt * 60;
    }
    // clamp velocity
    const speed = Math.hypot(p.vx, p.vy);
    const maxSpeed = 0.6;
    if (speed > maxSpeed) { p.vx *= maxSpeed/speed; p.vy *= maxSpeed/speed; }

    p.x += p.vx * dt * 60;
    p.y += p.vy * dt * 60;

    // out mode: respawn opposite
    if (p.x < -20) p.x = width + 20;
    if (p.x > width + 20) p.x = -20;
    if (p.y < -20) p.y = height + 20;
    if (p.y > height + 20) p.y = -20;

    // opacity anim speed 0.25
    const o = Math.max(0, Math.min(1, p.baseOpacity * (0.5 + 0.5*Math.sin(t * 0.25 * p.opacitySpeed * 4 + p.opacityPhase))));
