    const s = Math.max(0.3, p.baseSize * (0.5 + 0.5*Math.sin(t * 0.333 * p.sizeSpeed * 4 + p.sizePhase)));

    ctx.globalAlpha = o;
    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.arc(p.x, p.y, s, 0, Math.PI*2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  raf = requestAnimationFrame(tick);
};
