// particles.ts
export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  baseSize: number;
  baseOpacity: number;
  opacitySpeed: number;
  opacityPhase: number;
  sizeSpeed: number;
  sizePhase: number;
}

const DEFAULT_COUNT = 355;

const rand = (min: number, max: number) => Math.random() * (max - min) + min;

export function initParticles(canvas: HTMLCanvasElement): () => void {
  const ctx = canvas.getContext("2d");
  if (!ctx) return () => {};

  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  let width = 0;
  let height = 0;
  let particles: Particle[] = [];
  let raf = 0;
  const mouse = { x: -9999, y: -9999 };

  const resize = () => {
    const rect = canvas.getBoundingClientRect();
    const area = rect.width * rect.height;
    width = rect.width;
    height = rect.height;
    canvas.width = Math.floor(width * dpr);
    canvas.height = Math.floor(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const count = Math.floor(Math.min(600, Math.max(80, (area / (1920 * 1080)) * DEFAULT_COUNT)));
    particles = Array.from({ length: count }, () => createParticle());
  };

  const createParticle = (x?: number, y?: number): Particle => ({
    x: x ?? rand(0, width),
    y: y ?? rand(0, height),
    vx: rand(-0.12, 0.12),
    vy: rand(-0.12, 0.12),
    size: rand(0.6, 2.4),
    baseSize: rand(0.6, 2.4),
    baseOpacity: rand(0.2, 0.6),
    opacitySpeed: rand(0.25, 0.6),
    opacityPhase: rand(0, Math.PI * 2),
    sizeSpeed: rand(0.2, 0.5),
    sizePhase: rand(0, Math.PI * 2),
  });

  const step = (time: number) => {
    ctx.clearRect(0, 0, width, height);
    const t = time / 1000;

    for (const p of particles) {
      // drift
      p.x += p.vx;
      p.y += p.vy;

      // out mode: respawn on the opposite edge (emergent starfield)
      if (p.x < -20) p.x = width + 20;
      else if (p.x > width + 20) p.x = -20;
      if (p.y < -20) p.y = height + 20;
      else if (p.y > height + 20) p.y = -20;

      // bubble interactivity on hover
      const dx = p.x - mouse.x;
      const dy = p.y - mouse.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 83.9 && dist > 0.001) {
        const factor = 83.9 / dist;
        p.x = mouse.x + dx * factor;
        p.y = mouse.y + dy * factor;
      }

      const opacity =
        p.baseOpacity * (0.5 + 0.5 * Math.sin(t * p.opacitySpeed + p.opacityPhase));
      const size =
        p.baseSize * (0.5 + 0.5 * Math.sin(t * p.sizeSpeed + p.sizePhase)) + 0.3;

      ctx.globalAlpha = Math.max(0, Math.min(1, opacity));
      ctx.beginPath();
      ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    raf = requestAnimationFrame(step);
  };

  const onMouseMove = (e: MouseEvent) => {
    const rect = canvas.getBoundingClientRect();
    mouse.x = e.clientX - rect.left;
    mouse.y = e.clientY - rect.top;
  };

  const onMouseLeave = () => {
    mouse.x = -9999;
    mouse.y = -9999;
  };

  const onClick = (e: MouseEvent) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    for (let i = 0; i < 4; i++) {
      particles.push(createParticle(x, y));
    }
  };

  resize();
  window.addEventListener("resize", resize);
  window.addEventListener("mousemove", onMouseMove);
  canvas.addEventListener("mouseleave", onMouseLeave);
  canvas.addEventListener("click", onClick);
  raf = requestAnimationFrame(step);

  return () => {
    cancelAnimationFrame(raf);
    window.removeEventListener("resize", resize);
    window.removeEventListener("mousemove", onMouseMove);
    canvas.removeEventListener("mouseleave", onMouseLeave);
    canvas.removeEventListener("click", onClick);
  };
}
```

